import sys

def merge_brute(ints):
    ints = sorted(ints)
    res = []
    cur = None
    for s, e in ints:
        if cur is None or s > cur[1]:
            if cur:
                res.append(cur)
            cur = [s, e]
        else:
            cur[1] = max(cur[1], e)
    if cur:
        res.append(cur)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    ints = []
    idx = 1
    for _ in range(n):
        s, e = int(data[idx]), int(data[idx + 1])
        idx += 2
        ints.append([s, e])
    res = merge_brute(ints)
    for s, e in res:
        print(s, e)

import sys

def merge_opt(ints):
    ints = sorted(ints)
    res = []
    cur = ints[0][:] if ints else None
    for s, e in ints[1:]:
        if s <= cur[1]:
            cur[1] = max(cur[1], e)
        else:
            res.append(cur)
            cur = [s, e]
    if cur is not None:
        res.append(cur)
    return res

